parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "should_save": {
      "type": "boolean",
      "description": "true if ANY meaningful data was extracted — name, email, phone, interests, travel style, budget, services discussed, or any booking intent detected. false ONLY for pure greetings or one-word replies with zero extractable information."
    },
    "name": {
      "type": "string",
      "description": "Full name of the user if explicitly mentioned. e.g. 'I'm John' or 'My name is Sarah Smith'. Empty string if not mentioned."
    },
    "email": {
      "type": "string",
      "description": "Email address if explicitly provided by the user. Must contain @ and a domain. Empty string if not mentioned."
    },
    "phone": {
      "type": "string",
      "description": "Phone number if explicitly provided. Empty string if not mentioned."
    },
    "status": {
      "type": "string",
      "enum": ["new", "engaged", "carted", "booked", "cold", ""],
      "description": "Lead status. Use 'engaged' if actively exploring services. Use 'carted' if something was added to cart this turn. Use 'booked' if a booking was completed. Use 'cold' if user showed no interest. Use 'new' for first meaningful interaction. Empty string if unclear."
    },
    "preferred_language": {
      "type": "string",
      "description": "Language the user is writing in. One word: English, Spanish, French, German, Portuguese, etc. Default to English if unclear."
    },
    "travel_style": {
      "type": "string",
      "enum": ["Adventure", "Relaxed", "Luxury", "Budget", "Mixed", ""],
      "description": "Infer from tone and interests. Empty string if not inferable."
    },
    "budget_range": {
      "type": "string",
      "description": "Any budget signals mentioned by user. e.g. 'under $200', '$300-$500 per person', 'flexible'. Empty string if not mentioned."
    },
    "interests": {
      "type": "string",
      "description": "Comma-separated activity interests detected from user messages. Options: Fishing, Wildlife, Beach, Snorkeling, ATV, Surfing, Waterfall, Cultural, Boat Charter, Sunset Cruise, Zip-line, Horseback Riding. Empty string if none detected."
    },
    "services_viewed": {
      "type": "string",
      "description": "Comma-separated names of tours or boat charters the user asked about or Neo described in this turn. Empty string if none."
    },
    "session_summary": {
      "type": "string",
      "description": "1-2 sentence rolling summary of the conversation. What does this person want and where are they in the booking journey? Empty string if nothing to summarize yet."
    },
    "ai_profile_summary": {
      "type": "string",
      "description": "2-3 sentence narrative written for a human sales agent who has never seen this conversation. Who is this traveler, what do they want, and how should the team follow up? Empty string if not enough data yet."
    }
  },
  "required": ["should_save", "name", "email", "phone", "status", "preferred_language", "travel_style", "budget_range", "interests", "services_viewed", "session_summary", "ai_profile_summary"]
}

